58	  let channel: RTCDataChannel | null = null
59	  const messageHandlers = new Set<(msg: PhoneMessage) => void>()
60	  const stateHandlers = new Set<(state: PeerState) => void>()
61	
62	  function setState(next: PeerState): void {
63	    if (state === next) return
64	    state = next
65	    for (const h of stateHandlers) h(next)
66	  }
67	
68	  function bindChannel(ch: RTCDataChannel): void {
69	    channel = ch
70	    ch.onopen = () => {
71	      if (state !== 'closed' && state !== 'error') setState('connected')
72	    }
73	    ch.onclose = () => {
74	      if (state !== 'error') setState('closed')
75	    }
76	    ch.onmessage = (ev: MessageEvent) => {
77	      if (typeof ev.data !== 'string') return
78	      const msg = decodePhoneMessage(ev.data)
79	      if (!msg) return
80	      for (const h of messageHandlers) h(msg)
81	    }
82	  }
83	
84	  pc.onconnectionstatechange = () => {
85	    const cs = pc.connectionState
86	    if (cs === 'connected' && state !== 'connected') setState('connecting')
87	    else if (cs === 'failed') setState('error')
88	    else if (cs === 'closed' && state !== 'closed') setState('closed')
89	  }
