130	    // already opened during ICE gathering, state is already 'connected' and
131	    // must not regress to 'connecting'.
132	    if (state === 'gathering_answer') setState('connecting')
133	    return pc.localDescription?.sdp ?? answer.sdp ?? ''
134	  }
135	
136	  async function acceptAnswer(answerSdp: string): Promise<void> {
137	    if (role !== 'offerer') throw new Error('only the offerer can accept an answer')
138	    await pc.setRemoteDescription({ type: 'answer', sdp: answerSdp })
139	    setState('connecting')
140	  }
