149	  function onMessage(handler: (msg: PhoneMessage) => void): () => void {
150	    messageHandlers.add(handler)
151	    return () => messageHandlers.delete(handler)
152	  }
153	
154	  function onStateChange(handler: (state: PeerState) => void): () => void {
155	    stateHandlers.add(handler)
156	    return () => stateHandlers.delete(handler)
157	  }
158	
159	  function close(): void {
160	    try {
161	      channel?.close()
162	    } catch {
163	      /* ignore */
164	    }
165	    try {
166	      pc.close()
167	    } catch {
168	      /* ignore */
169	    }
170	    setState('closed')
171	  }
172	
173	  return {
174	    get state() {
175	      return state
176	    },
177	    createOffer,
178	    acceptOffer,
179	    acceptAnswer,
180	    send,
181	    onMessage,
182	    onStateChange,
183	    close,
184	  }
