import { useEffect, useRef, useState } from 'react'
import { createPeer, type PeerHandle, type PeerState } from '../phone/peer'
import type { PhoneMessage } from '../phone/wire'
import { loadSettings } from '../store/settings'

interface PairScreenProps {
  onClose: () => void
}

/**
 * Phase 2b.1 — laptop-side pairing UI. Manual SDP copy/paste.
 *
 * Intentional throwaway UX (decision memo §"Throwaway scaffolding"): the
 * two-textarea flow ships only to prove the WebRTC DataChannel transport.
 * Phase 2b.2 replaces this with QR scanning; the only parts that survive
 * past 2b.1 are `phone/peer.ts`, `phone/wire.ts`, and the `/phone` route.
 */
export function PairScreen({ onClose }: PairScreenProps) {
  const peerRef = useRef<PeerHandle | null>(null)
  const [state, setState] = useState<PeerState>('idle')
  const [offerText, setOfferText] = useState('')
  const [answerText, setAnswerText] = useState('')
  const [phoneUrl, setPhoneUrl] = useState<string | null>(null)
  const [err, setErr] = useState<string | null>(null)
  const [startedAt, setStartedAt] = useState<number | null>(null)
  const [lastCommit, setLastCommit] = useState<{
    receivedAt: number
    sentAt: number
  } | null>(null)

  useEffect(() => {
    let cancelled = false
    void loadSettings().then((s) => {
      if (cancelled) return
      const ip = s.laptopLanIp?.trim()
      // window.location.port is always present when the SPA itself is loaded
      // (the laptop is reading this page); the URL we render is whatever
      // origin served us, so the phone hits the same port.
      const port = window.location.port
      if (ip) setPhoneUrl(`http://${ip}:${port}/phone`)
    })
    return () => {
      cancelled = true
      peerRef.current?.close()
    }
  }, [])

  async function handleGenerateOffer(): Promise<void> {
    setErr(null)
    if (peerRef.current) {
      setErr('Already generated an offer — reload to start over.')
      return
    }
    try {
      const peer = createPeer()
      peerRef.current = peer
      peer.onStateChange(setState)
      peer.onMessage((m: PhoneMessage) => {
        if (m.type === 'commit') {
          setLastCommit({ receivedAt: Date.now(), sentAt: m.t })
        }
      })
      setStartedAt(Date.now())
      const offer = await peer.createOffer()
      setOfferText(offer)
    } catch (e) {
      setErr(e instanceof Error ? e.message : String(e))
    }
  }

  async function handleAcceptAnswer(): Promise<void> {
    setErr(null)
    const peer = peerRef.current
    if (!peer) {
      setErr('Generate an offer first.')
      return
    }
    if (!answerText.trim()) {
      setErr('Paste the answer SDP from the phone.')
      return
    }
    try {
      await peer.acceptAnswer(answerText)
    } catch (e) {
      setErr(e instanceof Error ? e.message : String(e))
    }
  }

  const sinceStart =
    startedAt !== null && lastCommit
      ? lastCommit.receivedAt - startedAt
      : null

  return (
    <div className="screen pair-screen">
      <header className="settings-header">
        <h1>Pair phone (Phase 2b.1)</h1>
        <button type="button" className="link" onClick={onClose}>
          Close
        </button>
      </header>

      <p className="hint">
        Manual SDP pairing — temporary scaffolding. Phase 2b.2 replaces this
        with QR scanning.
      </p>

      <section className="settings-section">
        <h2>1. Open the phone companion page</h2>
        {phoneUrl ? (
          <p>
            On your phone, open <code data-testid="phone-url">{phoneUrl}</code>.
          </p>
        ) : (
          <p className="hint">
            Set your laptop's LAN IP in Settings to see the phone URL here.
          </p>
        )}
      </section>

      <section className="settings-section">
        <h2>2. Generate an offer</h2>
        <button
          type="button"
          className="primary"
          onClick={() => void handleGenerateOffer()}
          disabled={state !== 'idle' && state !== 'error'}
        >
          Generate offer
        </button>
        <textarea
          aria-label="offer SDP"
          rows={6}
          value={offerText}
          readOnly
          placeholder="(generated by clicking Generate offer)"
        />
        <p className="hint">Copy this whole block onto the phone screen.</p>
      </section>

      <section className="settings-section">
        <h2>3. Paste the phone's answer</h2>
        <textarea
          aria-label="answer SDP"
          rows={6}
          value={answerText}
          onChange={(e) => setAnswerText(e.target.value)}
          placeholder="v=0…"
        />
        <button
          type="button"
          className="primary"
          onClick={() => void handleAcceptAnswer()}
          disabled={state !== 'awaiting_answer'}
        >
          Connect
        </button>
      </section>

      <section className="settings-section">
        <h2>4. Status</h2>
        <p>
          Connection: <strong data-testid="pair-state">{state}</strong>
        </p>
        {lastCommit && (
          <p data-testid="last-commit">
            Last commit received at +{sinceStart}ms (phone clock t=
            {lastCommit.sentAt}).
          </p>
        )}
      </section>

      {err && (
        <div className="banner warn" role="alert">
          {err}
        </div>
      )}
    </div>
  )
}

import { useEffect, useState } from 'react'
import {
  DEFAULT_SETTINGS,
  loadActiveProfile,
  loadSettings,
  saveSettings,
  setActiveProfile,
  type SettingsRecord,
} from '../store/settings'
import {
  buildDefaultProfile,
  deleteProfile,
  listProfiles,
  saveProfile,
  type ProfileRecord,
} from '../store/profiles'
import { validateDrillConfig } from '../engine/drill'
import { buildTaperProfileBlueprint } from '../engine/analytics'
import { listRecentSessions, listRepsForSessions } from '../store/db'
import { CUE_LIBRARY } from '../cues/library'
import {
  DEFAULT_DRILL_CONFIG,
  PRE_CUE_MAX_CEILING_MS,
  PRE_CUE_MIN_FLOOR_MS,
  type CueId,
  type DrillConfig,
  type InputSource,
  type RepResult,
} from '../engine/types'

interface SettingsScreenProps {
  onClose: () => void
  onOpenPair?: () => void
}

const SCORE_FIELDS: { key: RepResult; label: string }[] = [
  { key: 'correct_go', label: 'Correct go' },
  { key: 'correct_no_go', label: 'Correct no-go' },
  { key: 'late', label: 'Late' },
  { key: 'hesitation', label: 'Hesitation' },
  { key: 'false_start', label: 'False start' },
]

export function SettingsScreen({ onClose, onOpenPair }: SettingsScreenProps) {
  const [settings, setSettings] = useState<SettingsRecord>(DEFAULT_SETTINGS)
  const [profile, setProfile] = useState<ProfileRecord | null>(null)
  const [profiles, setProfiles] = useState<ProfileRecord[]>([])
  const [loaded, setLoaded] = useState(false)
  const [rebinding, setRebinding] = useState(false)
  const [errors, setErrors] = useState<string[]>([])
  const [taperReason, setTaperReason] = useState<string | null>(null)
  const [taperError, setTaperError] = useState<string | null>(null)

  useEffect(() => {
    let cancelled = false
    void Promise.all([loadSettings(), loadActiveProfile(), listProfiles()]).then(
      ([s, p, all]) => {
        if (cancelled) return
        setSettings(s)
        setProfile(p)
        setProfiles(all)
        setLoaded(true)
      },
    )
    return () => {
      cancelled = true
    }
  }, [])

  useEffect(() => {
    if (!rebinding) return
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        setRebinding(false)
        return
      }
      e.preventDefault()
      setSettings((prev) => ({
        ...prev,
        commitKeyCode: e.code,
        commitKeyLabel: humanizeKeyCode(e.code, e.key),
      }))
      setRebinding(false)
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [rebinding])

  function updateSettings<K extends keyof SettingsRecord>(
    key: K,
    value: SettingsRecord[K],
  ): void {
    setSettings((prev) => ({ ...prev, [key]: value }))
  }

  function updateConfig<K extends keyof DrillConfig>(
    key: K,
    value: DrillConfig[K],
  ): void {
    setProfile((prev) =>
      prev ? { ...prev, config: { ...prev.config, [key]: value } } : prev,
    )
  }

  function updateScoreWeight(result: RepResult, value: number): void {
    setProfile((prev) =>
      prev
        ? {
            ...prev,
            config: {
              ...prev.config,
              scoreWeights: { ...prev.config.scoreWeights, [result]: value },
            },
          }
        : prev,
    )
  }

  function toggleAllowedCue(cueId: CueId): void {
    setProfile((prev) => {
      if (!prev) return prev
      const current = prev.config.allowedCueIds ?? CUE_LIBRARY.map((c) => c.id)
      const set = new Set(current)
      if (set.has(cueId)) set.delete(cueId)
      else set.add(cueId)
      const next =
        set.size === CUE_LIBRARY.length ? null : Array.from(set)
      return { ...prev, config: { ...prev.config, allowedCueIds: next } }
    })
  }

  async function handleSave() {
    if (!profile) return
    const errs = validateDrillConfig(profile.config)
    if (errs.length > 0) {
      setErrors(errs.map((e) => `${e.field}: ${e.message}`))
      return
    }
    setErrors([])
    await saveProfile(profile)
    await saveSettings(settings)
    onClose()
  }

  async function handleSwitchProfile(id: string) {
    if (!id || id === profile?.id) return
    await setActiveProfile(id)
    const next = profiles.find((p) => p.id === id)
    if (next) setProfile(next)
    setSettings((prev) => ({ ...prev, activeProfileId: id }))
  }

  async function handleCreateProfile() {
    const name = prompt('New profile name?', `Profile ${profiles.length + 1}`)
    if (!name) return
    const base = profile
      ? { ...profile.config }
      : { ...DEFAULT_DRILL_CONFIG }
    const fresh = { ...buildDefaultProfile(base), name }
    await saveProfile(fresh)
    await setActiveProfile(fresh.id)
    setProfile(fresh)
    setProfiles((prev) => [...prev, fresh])
    setSettings((prev) => ({ ...prev, activeProfileId: fresh.id }))
  }

  async function handleRenameProfile() {
    if (!profile) return
    const name = prompt('Rename profile to:', profile.name)
    if (!name) return
    const renamed = { ...profile, name }
    await saveProfile(renamed)
    setProfile(renamed)
    setProfiles((prev) => prev.map((p) => (p.id === renamed.id ? renamed : p)))
  }

  async function handleDeleteProfile() {
    if (!profile) return
    if (profiles.length <= 1) {
      setErrors(['Cannot delete the only remaining profile.'])
      return
    }
    if (!confirm(`Delete profile "${profile.name}"?`)) return
    const remaining = profiles.filter((p) => p.id !== profile.id)
    await deleteProfile(profile.id)
    await setActiveProfile(remaining[0].id)
    setProfile(remaining[0])
    setProfiles(remaining)
    setSettings((prev) => ({ ...prev, activeProfileId: remaining[0].id }))
  }

  async function handleBuildTaperProfile() {
    const sessions = await listRecentSessions(5)
    if (sessions.length === 0) {
      setTaperError('No sessions yet — run a drill first.')
      setTaperReason(null)
      return
    }
    const reps = await listRepsForSessions(sessions.map((s) => s.id))
    const blueprint = buildTaperProfileBlueprint(
      sessions,
      reps,
      profile?.config ?? DEFAULT_DRILL_CONFIG,
      3,
    )
    if (!blueprint) {
      setTaperError(
        'Not enough data to pick taper cues. Drill more variety first.',
      )
      setTaperReason(null)
      return
    }
    const today = new Date().toISOString().slice(0, 10)
    const fresh = {
      ...buildDefaultProfile(blueprint.config),
      name: `Taper — ${today}`,
    }
    await saveProfile(fresh)
    await setActiveProfile(fresh.id)
    setProfile(fresh)
    setProfiles((prev) => [...prev, fresh])
    setSettings((prev) => ({ ...prev, activeProfileId: fresh.id }))
    setTaperReason(blueprint.reason)
    setTaperError(null)
  }

  if (!loaded || !profile) {
    return (
      <div className="screen settings">
        <p>Loading settings…</p>
      </div>
    )
  }

  const config = profile.config
  const allowedCueIds = config.allowedCueIds ?? CUE_LIBRARY.map((c) => c.id)
  const allowedSet = new Set(allowedCueIds)

  return (
    <div className="screen settings">
      <header className="settings-header">
        <h1>Settings</h1>
        <button type="button" className="link" onClick={onClose}>
          Cancel
        </button>
      </header>

      <section className="settings-section">
        <h2>Profile</h2>
        <label>
          <span>Active profile</span>
          <select
            value={profile.id}
            onChange={(e) => void handleSwitchProfile(e.target.value)}
            aria-label="active profile"
          >
            {profiles.map((p) => (
              <option key={p.id} value={p.id}>
                {p.name}
              </option>
            ))}
          </select>
        </label>
        <div className="profile-actions">
          <button
            type="button"
            className="link"
            onClick={() => void handleCreateProfile()}
          >
            New profile
          </button>
          <button
            type="button"
            className="link"
            onClick={() => void handleRenameProfile()}
          >
            Rename
          </button>
          <button
            type="button"
            className="link"
