        if (cancelled) return
        setOfferSdp(sdp)
        const enc = await tryEncodeOffer(sdp)
        if (!enc.ok) {
          setMode('manual')
          setAutoFallbackReason(
            `Pairing payload (${enc.byteLength} bytes) is too large for one QR — using manual paste.`,
          )
          setQrState('showing-offer')
          return
        }
        if (!ip) {
          setMode('manual')
          setAutoFallbackReason(
            'Set your laptop’s LAN IP in Settings to enable QR pairing. Using manual paste.',
          )
          setQrState('showing-offer')
          return
        }
        const url = buildPhoneUrl(
          {
            protocol: window.location.protocol,
            lanIp: ip,
            port: window.location.port,
          },
          enc.payload,
        )
        setPhoneUrl(url)
        setQrState('showing-offer')
      } catch (e) {
        setErr(e instanceof Error ? e.message : String(e))
        setQrState('error')
      }
    })()
    return () => {
      cancelled = true
      stopScanning()
      peerRef.current?.close()
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  // --- Draw the offer QR onto its canvas once we have a phoneUrl ---
  useEffect(() => {
    if (!phoneUrl) return
    const canvas = qrCanvasRef.current
    if (!canvas) return
    void QRCode.toCanvas(canvas, phoneUrl, {
      margin: 1,
      width: 320,
      errorCorrectionLevel: 'L',
    }).catch((e: unknown) => {
      setErr(e instanceof Error ? e.message : String(e))
    })
  }, [phoneUrl])

  function stopScanning(): void {
    if (scanRafRef.current !== null) {
      cancelAnimationFrame(scanRafRef.current)
      scanRafRef.current = null
    }
    if (streamRef.current) {
      for (const t of streamRef.current.getTracks()) t.stop()
      streamRef.current = null
    }
  }

  async function handleStartScan(): Promise<void> {
    setErr(null)
    const gum =
      getUserMedia ??
      navigator.mediaDevices?.getUserMedia.bind(navigator.mediaDevices)
    if (!gum) {
      setMode('manual')
      setAutoFallbackReason('No camera available — use manual pairing below.')
      return
    }
    let stream: MediaStream
    try {
      stream = await gum({ video: { facingMode: 'user' } })
    } catch (e) {
      setMode('manual')
      setAutoFallbackReason(
        e instanceof Error && e.name === 'NotAllowedError'
          ? 'Camera blocked — use manual pairing below.'
          : `Camera unavailable (${e instanceof Error ? e.message : String(e)}) — use manual pairing below.`,
      )
      return
    }
    streamRef.current = stream
    const video = videoRef.current
    if (!video) return
    video.srcObject = stream
    await video.play().catch(() => {})
    setQrState('scanning-answer')
    scheduleScan()
  }

  function scheduleScan(): void {
    if (scanRafRef.current !== null) return
    const tick = () => {
      scanRafRef.current = null
      const video = videoRef.current
      const canvas = canvasRef.current
      if (!video || !canvas) return
      const w = video.videoWidth
      const h = video.videoHeight
      if (!w || !h) {
        scanRafRef.current = requestAnimationFrame(tick)
        return
      }
      canvas.width = w
      canvas.height = h
      const ctx = canvas.getContext('2d')
      if (!ctx) return
      ctx.drawImage(video, 0, 0, w, h)
      const image = ctx.getImageData(0, 0, w, h)
      const result = jsQR(image.data, w, h)
      if (result && result.data) {
        void handleDecodedAnswer(result.data)
        return
      }
      scanRafRef.current = requestAnimationFrame(tick)
    }
    scanRafRef.current = requestAnimationFrame(tick)
  }

  async function handleDecodedAnswer(payload: string): Promise<void> {
    const dec = await tryDecodeOffer(payload)
    if (!dec.ok) {
      // Keep scanning; QR decoded but content is wrong shape (could be any
      // QR in the camera's view). Resume the scan loop.
      scheduleScan()
      return
    }
    stopScanning()
    setAnswerSdp(dec.sdp)
    try {
      await peerRef.current?.acceptAnswer(dec.sdp)
    } catch (e) {
      setErr(e instanceof Error ? e.message : String(e))
      setQrState('error')
    }
  }

  async function handleManualAcceptAnswer(): Promise<void> {
    setErr(null)
    if (!answerSdp.trim()) {
      setErr('Paste the answer SDP from the phone.')
      return
    }
    try {
      await peerRef.current?.acceptAnswer(answerSdp)
    } catch (e) {
      setErr(e instanceof Error ? e.message : String(e))
    }
  }

  function toggleMode(): void {
    setMode((m) => (m === 'qr' ? 'manual' : 'qr'))
    if (mode === 'qr') stopScanning()
  }

  const sinceStart =
    startedAt !== null && lastCommit
      ? lastCommit.receivedAt - startedAt
      : null

  return (
    <div className="screen pair-screen">
      <header className="settings-header">
        <h1>Pair phone</h1>
        <button type="button" className="link" onClick={onClose}>
          Close
        </button>
      </header>

      <p className="hint">
        QR pairing (Phase 2b.2). Manual paste remains available as a fallback.
      </p>

      <div className="profile-actions">
        <button
          type="button"
          className="link"
          onClick={toggleMode}
          aria-label="toggle pair mode"
        >
          {mode === 'qr' ? 'Show manual pairing' : 'Back to QR pairing'}
        </button>
      </div>

      {autoFallbackReason && mode === 'manual' && (
        <div className="banner info" role="status">
          {autoFallbackReason}
        </div>
      )}

      {mode === 'qr' ? (
        <QrPanel
          qrState={qrState}
          phoneUrl={phoneUrl}
          lanIp={lanIp}
          qrCanvasRef={qrCanvasRef}
          videoRef={videoRef}
          canvasRef={canvasRef}
          onStartScan={() => void handleStartScan()}
        />
      ) : (
        <ManualPanel
          phoneUrl={phoneUrlForManual(lanIp)}
          offerSdp={offerSdp}
          answerSdp={answerSdp}
          peerState={peerState}
          onAnswerChange={setAnswerSdp}
          onAccept={() => void handleManualAcceptAnswer()}
        />
      )}

      <section className="settings-section">
        <h2>Status</h2>
        <p>
          Connection: <strong data-testid="pair-state">{qrState}</strong>{' '}
          (peer: <span data-testid="peer-state">{peerState}</span>)
        </p>
        {lastCommit && (
          <p data-testid="last-commit">
            Last commit received at +{sinceStart}ms (phone clock t=
            {lastCommit.sentAt}).
          </p>
        )}
      </section>

      {err && (
        <div className="banner warn" role="alert">
          {err}
        </div>
      )}
    </div>
  )
}

function QrPanel({
  qrState,
  phoneUrl,
  lanIp,
  qrCanvasRef,
  videoRef,
  canvasRef,
  onStartScan,
}: {
  qrState: PairQrState
  phoneUrl: string | null
  lanIp: string | null
  qrCanvasRef: React.RefObject<HTMLCanvasElement | null>
  videoRef: React.RefObject<HTMLVideoElement | null>
  canvasRef: React.RefObject<HTMLCanvasElement | null>
  onStartScan: () => void
}) {
  return (
    <>
      <section className="settings-section">
        <h2>1. Scan with your phone</h2>
        {phoneUrl ? (
          <>
            <canvas ref={qrCanvasRef} data-testid="offer-qr" />
            <p className="hint">
              Or open <code data-testid="phone-url">{phoneUrl}</code> manually.
            </p>
          </>
        ) : (
          <p className="hint" data-testid="qr-pending">
            {lanIp ? 'Preparing offer…' : 'Set your laptop’s LAN IP in Settings to render a QR.'}
          </p>
        )}
      </section>

      <section className="settings-section">
        <h2>2. Scan the phone's reply</h2>
        {qrState === 'scanning-answer' || qrState === 'connected' ? (
          <>
            <video
              ref={videoRef}
              data-testid="answer-video"
              playsInline
              muted
              style={{ maxWidth: 320 }}
            />
            <canvas
              ref={canvasRef}
              data-testid="answer-canvas"
              style={{ display: 'none' }}
            />
          </>
        ) : (
          <button
            type="button"
            className="primary"
            onClick={onStartScan}
            disabled={qrState !== 'showing-offer'}
            aria-label="start scan"
          >
            I scanned the QR — turn on camera
          </button>
        )}
      </section>
    </>
  )
}

function ManualPanel({
  phoneUrl,
  offerSdp,
  answerSdp,
  peerState,
  onAnswerChange,
  onAccept,
}: {
  phoneUrl: string | null
  offerSdp: string
  answerSdp: string
  peerState: PeerState
  onAnswerChange: (v: string) => void
  onAccept: () => void
}) {
  return (
    <>
      <section className="settings-section">
        <h2>1. Open the phone companion page</h2>
        {phoneUrl ? (
          <p>
            On your phone, open <code data-testid="phone-url">{phoneUrl}</code>.
          </p>
        ) : (
          <p className="hint">
            Set your laptop's LAN IP in Settings to see the phone URL here.
          </p>
        )}
      </section>

      <section className="settings-section">
        <h2>2. Offer SDP (copy onto the phone)</h2>
        <textarea
          aria-label="offer SDP"
          rows={6}
          value={offerSdp}
          readOnly
          placeholder="(generating…)"
        />
      </section>

      <section className="settings-section">
        <h2>3. Paste the phone's answer SDP</h2>
        <textarea
          aria-label="answer SDP"
          rows={6}
          value={answerSdp}
          onChange={(e) => onAnswerChange(e.target.value)}
          placeholder="v=0…"
        />
        <button
          type="button"
          className="primary"
          onClick={onAccept}
          disabled={peerState !== 'awaiting_answer'}
        >
          Connect
        </button>
      </section>
    </>
  )
}

function buildPhoneUrl(lanIp: string, offerPayload: string): string {
  const protocol = window.location.protocol
  const port = window.location.port
  const portPart = port ? `:${port}` : ''
  return `${protocol}//${lanIp}${portPart}/phone#offer=${offerPayload}`
}

function phoneUrlForManual(lanIp: string | null): string | null {
  if (!lanIp) return null
  const protocol = window.location.protocol
  const port = window.location.port
  const portPart = port ? `:${port}` : ''
  return `${protocol}//${lanIp}${portPart}/phone`
}

import { useEffect, useRef, useState } from 'react'
import QRCode from 'qrcode'
import { createPeer, type PeerHandle, type PeerState } from './peer'
import { tryDecodeOffer, tryEncodeOffer } from './qr'

export type PhoneMode = 'qr' | 'manual'

export function PhoneApp() {
  const peerRef = useRef<PeerHandle | null>(null)
  const answerQrRef = useRef<HTMLCanvasElement | null>(null)

  const [state, setState] = useState<PeerState>('idle')
  const [mode, setMode] = useState<PhoneMode>('qr')
  const [offerText, setOfferText] = useState('')
  const [answerText, setAnswerText] = useState('')
  const [answerPayload, setAnswerPayload] = useState<string | null>(null)
  const [autoFallbackReason, setAutoFallbackReason] = useState<string | null>(
    null,
  )
  const [fragmentTried, setFragmentTried] = useState(false)
  const [err, setErr] = useState<string | null>(null)
  const [lastCommitAt, setLastCommitAt] = useState<number | null>(null)

  useEffect(() => {
    let cancelled = false
    const fragment = window.location.hash?.slice(1) ?? ''
    const params = new URLSearchParams(fragment)
    const offerPayload = params.get('offer')
    if (!offerPayload) {
      setFragmentTried(true)
      setMode('manual')
      return
    }

    void (async () => {
      const dec = await tryDecodeOffer(offerPayload)
      if (cancelled) return
      if (!dec.ok) {
        setFragmentTried(true)
        setMode('manual')
        setAutoFallbackReason(
          dec.reason === 'b64'
            ? 'QR payload could not be read — paste the offer manually.'
            : dec.reason === 'gzip'
              ? 'QR payload could not be decompressed — paste the offer manually.'
              : 'QR payload was empty — paste the offer manually.',
        )
        return
      }
      try {
        const peer = createPeer()
        peerRef.current = peer
        peer.onStateChange(setState)
        const answerSdp = await peer.acceptOffer(dec.sdp)
        if (cancelled) return
        setAnswerText(answerSdp)
        const enc = await tryEncodeOffer(answerSdp)
        if (!enc.ok) {
          setMode('manual')
          setAutoFallbackReason(
            `Answer SDP is too large for one QR (${enc.byteLength} bytes) — copy it manually.`,
          )
          setFragmentTried(true)
          return
        }
        setAnswerPayload(enc.payload)
        setFragmentTried(true)
      } catch (e) {
        if (cancelled) return
        setFragmentTried(true)
        setMode('manual')
        setAutoFallbackReason(
          `Could not apply offer from QR (${e instanceof Error ? e.message : String(e)}) — paste it manually.`,
        )
      }
    })()

    return () => {
      cancelled = true
      peerRef.current?.close()
    }
  }, [])

  useEffect(() => {
    if (!answerPayload) return
    const canvas = answerQrRef.current
    if (!canvas) return
    void QRCode.toCanvas(canvas, answerPayload, {
      margin: 1,
      width: 320,
      errorCorrectionLevel: 'L',
    }).catch((e: unknown) => {
      setErr(e instanceof Error ? e.message : String(e))
    })
  }, [answerPayload])

  async function handleAcceptOffer(): Promise<void> {
    setErr(null)
    if (!offerText.trim()) {
      setErr('Paste the offer SDP from the laptop first.')
      return
    }
    if (peerRef.current) {
      setErr('Already paired this session — reload the page to start over.')
      return
    }
    try {
      const peer = createPeer()
      peerRef.current = peer
      peer.onStateChange(setState)
      const answer = await peer.acceptOffer(offerText)
      setAnswerText(answer)
    } catch (e) {
      setErr(e instanceof Error ? e.message : String(e))
    }
  }

  function handleSendCommit(): void {
    setErr(null)
    const peer = peerRef.current
    if (!peer || state !== 'connected') {
      setErr('Not connected yet.')
      return
    }
    const t = Date.now()
    try {
      peer.send({ type: 'commit', t })
      setLastCommitAt(t)
    } catch (e) {
      setErr(e instanceof Error ? e.message : String(e))
    }
  }

  return (
    <div className="screen phone-app">
      <header>
        <h1>PointFight Phone Sensor</h1>
        <p className="hint">
          {mode === 'qr'
            ? 'QR pairing (Phase 2b.2). Show this screen to the laptop’s webcam.'
            : 'Manual pairing fallback.'}
        </p>
      </header>

      <div className="profile-actions">
        <button
          type="button"
          className="link"
          onClick={() => setMode((m) => (m === 'qr' ? 'manual' : 'qr'))}
          aria-label="toggle phone mode"
        >
          {mode === 'qr' ? 'Show manual paste' : 'Back to QR'}
        </button>
      </div>

      {autoFallbackReason && mode === 'manual' && (
        <div className="banner info" role="status" data-testid="phone-fallback">
          {autoFallbackReason}
        </div>
      )}

      {mode === 'qr' && fragmentTried && answerPayload && (
        <section className="settings-section">
          <h2>Show this QR to the laptop</h2>
          <canvas ref={answerQrRef} data-testid="answer-qr" />
          <p className="hint">
            The laptop's webcam will scan this to complete pairing.
          </p>
        </section>
      )}

      {mode === 'qr' && fragmentTried && !answerPayload && (
        <section className="settings-section">
          <p className="hint" data-testid="qr-pending">
            Open this page via the laptop's offer QR (URL contains{' '}
            <code>#offer=…</code>) to generate an answer QR.
          </p>
        </section>
      )}

      {mode === 'manual' && (
        <>
          <section className="settings-section">
            <h2>1. Paste the offer SDP from the laptop</h2>
            <textarea
              aria-label="offer SDP"
              rows={6}
              value={offerText}
              onChange={(e) => setOfferText(e.target.value)}
              placeholder="v=0…"
            />
            <button
              type="button"
              className="primary"
              onClick={() => void handleAcceptOffer()}
              disabled={state !== 'idle' && state !== 'error'}
            >
              Generate answer
            </button>
          </section>

          <section className="settings-section">
            <h2>2. Copy this answer back to the laptop</h2>
            <textarea
              aria-label="answer SDP"
              rows={6}
              value={answerText}
              readOnly
              placeholder="(generated after step 1)"
            />
          </section>
        </>
      )}

      <section className="settings-section">
        <h2>Send a commit</h2>
        <p>
          Status: <strong data-testid="phone-state">{state}</strong>
        </p>
        <button
          type="button"
          className="primary"
          onClick={handleSendCommit}
          disabled={state !== 'connected'}
        >
          Send commit
        </button>
        {lastCommitAt !== null && (
          <p className="hint">Last commit sent at {lastCommitAt}</p>
        )}
      </section>

      {err && (
        <div className="banner warn" role="alert">
          {err}
        </div>
      )}
    </div>
  )
}

