1	/**
2	 * Phase 2b.2 — offer/answer SDP <-> URL-fragment payload.
3	 *
4	 * Wire shape: `<gzip(sdpUtf8)>` then base64url-encoded.
5	 * The payload rides in the laptop->phone QR as `…/phone#offer=<payload>`,
6	 * and in the phone->laptop QR as a bare payload string the laptop's
7	 * webcam decodes back to an SDP answer.
8	 *
9	 * Threshold rationale: QR Version 25 / EC-L holds ~1273 bytes in byte
10	 * mode. We cap at 1200 to leave room for the URL prefix and a small
11	 * safety margin. Compressed SDPs are typically ~0.6–1.2 KB; oversize is
12	 * the exception, not the rule.
13	 */
14	
15	export const QR_PAYLOAD_THRESHOLD_BYTES = 1200
16	
17	export type EncodeResult =
18	  | { ok: true; payload: string; byteLength: number }
19	  | { ok: false; reason: 'oversize'; byteLength: number }
20	
21	export type DecodeResult =
22	  | { ok: true; sdp: string }
23	  | { ok: false; reason: 'empty' | 'b64' | 'gzip' }
24	
25	export async function tryEncodeOffer(sdp: string): Promise<EncodeResult> {
26	  const compressed = await gzip(new TextEncoder().encode(sdp))
27	  const payload = base64UrlEncode(compressed)
28	  const byteLength = payload.length
29	  if (byteLength > QR_PAYLOAD_THRESHOLD_BYTES) {
30	    return { ok: false, reason: 'oversize', byteLength }
31	  }
32	  return { ok: true, payload, byteLength }
33	}
34	
35	export async function tryDecodeOffer(payload: string): Promise<DecodeResult> {
36	  if (!payload) return { ok: false, reason: 'empty' }
37	  let bytes: Uint8Array
38	  try {
39	    bytes = base64UrlDecode(payload)
40	  } catch {
41	    return { ok: false, reason: 'b64' }
42	  }
43	  let sdpBytes: Uint8Array
44	  try {
45	    sdpBytes = await gunzip(bytes)
46	  } catch {
47	    return { ok: false, reason: 'gzip' }
48	  }
49	  return { ok: true, sdp: new TextDecoder().decode(sdpBytes) }
50	}
51	
52	async function gzip(input: Uint8Array): Promise<Uint8Array> {
53	  return runStream(input, new CompressionStream('gzip'))
54	}
55	
56	async function gunzip(input: Uint8Array): Promise<Uint8Array> {
57	  return runStream(input, new DecompressionStream('gzip'))
58	}
59	
60	async function runStream(
61	  input: Uint8Array,
62	  transform: GenericTransformStream,
63	): Promise<Uint8Array> {
64	  const source = new ReadableStream<Uint8Array>({
65	    start(controller) {
66	      controller.enqueue(input)
67	      controller.close()
68	    },
69	  })
70	  const out = source.pipeThrough(transform)
71	  const reader = (out as ReadableStream<Uint8Array>).getReader()
72	  const chunks: Uint8Array[] = []
73	  let total = 0
74	  for (;;) {
75	    const { value, done } = await reader.read()
76	    if (done) break
77	    if (value) {
78	      chunks.push(value)
79	      total += value.length
80	    }
81	  }
82	  const result = new Uint8Array(total)
83	  let offset = 0
84	  for (const chunk of chunks) {
85	    result.set(chunk, offset)
86	    offset += chunk.length
87	  }
88	  return result
89	}
90	
91	function base64UrlEncode(bytes: Uint8Array): string {
92	  let bin = ''
93	  for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i])
94	  const b64 = typeof btoa === 'function'
95	    ? btoa(bin)
96	    : Buffer.from(bin, 'binary').toString('base64')
97	  return b64.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '')
98	}
99	
100	function base64UrlDecode(payload: string): Uint8Array {
101	  if (!/^[A-Za-z0-9_-]*$/.test(payload)) throw new Error('not base64url')
102	  let b64 = payload.replace(/-/g, '+').replace(/_/g, '/')
103	  while (b64.length % 4) b64 += '='
104	  const bin = typeof atob === 'function'
105	    ? atob(b64)
106	    : Buffer.from(b64, 'base64').toString('binary')
107	  const out = new Uint8Array(bin.length)
108	  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i)
109	  return out
110	}
