1	import {
2	  decodePhoneMessage,
3	  encodePhoneMessage,
4	  type PhoneMessage,
5	} from './wire'
6	
7	export type PeerState =
8	  | 'idle'
9	  | 'gathering_offer'
10	  | 'awaiting_answer'
11	  | 'gathering_answer'
12	  | 'connecting'
13	  | 'connected'
14	  | 'closed'
15	  | 'error'
16	
17	export type PeerConnectionFactory = (
18	  config?: RTCConfiguration,
19	) => RTCPeerConnection
20	
21	export interface CreatePeerOptions {
22	  /** Override RTCPeerConnection construction for tests. */
23	  peerConnectionFactory?: PeerConnectionFactory
24	  /** Custom ICE servers; defaults to a single public Google STUN. */
25	  iceServers?: RTCIceServer[]
26	  /** DataChannel label; both ends must agree. */
27	  channelLabel?: string
28	}
29	
30	export interface PeerHandle {
31	  readonly state: PeerState
32	  createOffer(): Promise<string>
33	  acceptOffer(offerSdp: string): Promise<string>
34	  acceptAnswer(answerSdp: string): Promise<void>
35	  send(msg: PhoneMessage): void
36	  onMessage(handler: (msg: PhoneMessage) => void): () => void
37	  onStateChange(handler: (state: PeerState) => void): () => void
38	  close(): void
39	}
40	
41	const DEFAULT_STUN: RTCIceServer = {
42	  urls: 'stun:stun.l.google.com:19302',
43	}
44	const DEFAULT_LABEL = 'pointfight-phone'
45	
46	export function createPeer(opts: CreatePeerOptions = {}): PeerHandle {
47	  const factory: PeerConnectionFactory =
48	    opts.peerConnectionFactory ??
49	    ((config) => new RTCPeerConnection(config))
50	
51	  const pc = factory({
52	    iceServers: opts.iceServers ?? [DEFAULT_STUN],
53	  })
54	
55	  const channelLabel = opts.channelLabel ?? DEFAULT_LABEL
56	  let state: PeerState = 'idle'
57	  let role: 'offerer' | 'answerer' | null = null
58	  let channel: RTCDataChannel | null = null
59	  const messageHandlers = new Set<(msg: PhoneMessage) => void>()
60	  const stateHandlers = new Set<(state: PeerState) => void>()
61	
62	  function setState(next: PeerState): void {
63	    if (state === next) return
64	    state = next
65	    for (const h of stateHandlers) h(next)
66	  }
67	
68	  function bindChannel(ch: RTCDataChannel): void {
69	    channel = ch
70	    ch.onopen = () => {
71	      if (state !== 'closed' && state !== 'error') setState('connected')
72	    }
73	    ch.onclose = () => {
74	      if (state !== 'error') setState('closed')
75	    }
76	    ch.onmessage = (ev: MessageEvent) => {
77	      if (typeof ev.data !== 'string') return
78	      const msg = decodePhoneMessage(ev.data)
79	      if (!msg) return
80	      for (const h of messageHandlers) h(msg)
81	    }
82	  }
83	
84	  pc.onconnectionstatechange = () => {
85	    const cs = pc.connectionState
86	    if (cs === 'connected' && state !== 'connected') setState('connecting')
87	    else if (cs === 'failed') setState('error')
88	    else if (cs === 'closed' && state !== 'closed') setState('closed')
89	  }
90	
91	  pc.ondatachannel = (ev: RTCDataChannelEvent) => {
92	    bindChannel(ev.channel)
93	  }
94	
95	  async function waitForIceComplete(): Promise<void> {
96	    if (pc.iceGatheringState === 'complete') return
97	    await new Promise<void>((resolve) => {
98	      const handler = () => {
99	        if (pc.iceGatheringState === 'complete') {
100	          pc.onicegatheringstatechange = null
101	          resolve()
102	        }
103	      }
104	      pc.onicegatheringstatechange = handler
105	    })
106	  }
107	
108	  async function createOffer(): Promise<string> {
109	    if (role !== null) throw new Error('peer already in use')
110	    role = 'offerer'
111	    channel = pc.createDataChannel(channelLabel)
112	    bindChannel(channel)
113	    setState('gathering_offer')
114	    const offer = await pc.createOffer()
115	    await pc.setLocalDescription(offer)
116	    await waitForIceComplete()
117	    setState('awaiting_answer')
118	    return pc.localDescription?.sdp ?? offer.sdp ?? ''
119	  }
120	
121	  async function acceptOffer(offerSdp: string): Promise<string> {
122	    if (role !== null) throw new Error('cannot accept offer: peer already in use')
123	    role = 'answerer'
124	    setState('gathering_answer')
125	    await pc.setRemoteDescription({ type: 'offer', sdp: offerSdp })
126	    const answer = await pc.createAnswer()
127	    await pc.setLocalDescription(answer)
128	    await waitForIceComplete()
129	    // Guard against the ondatachannel + onopen race: if the remote channel
130	    // already opened during ICE gathering, state is already 'connected' and
131	    // must not regress to 'connecting'.
132	    if (state === 'gathering_answer') setState('connecting')
133	    return pc.localDescription?.sdp ?? answer.sdp ?? ''
134	  }
135	
136	  async function acceptAnswer(answerSdp: string): Promise<void> {
137	    if (role !== 'offerer') throw new Error('only the offerer can accept an answer')
138	    await pc.setRemoteDescription({ type: 'answer', sdp: answerSdp })
139	    setState('connecting')
140	  }
141	
142	  function send(msg: PhoneMessage): void {
143	    if (!channel || channel.readyState !== 'open') {
144	      throw new Error('phone DataChannel is not open')
145	    }
146	    channel.send(encodePhoneMessage(msg))
147	  }
148	
149	  function onMessage(handler: (msg: PhoneMessage) => void): () => void {
150	    messageHandlers.add(handler)
151	    return () => messageHandlers.delete(handler)
152	  }
153	
154	  function onStateChange(handler: (state: PeerState) => void): () => void {
155	    stateHandlers.add(handler)
156	    return () => stateHandlers.delete(handler)
157	  }
158	
159	  function close(): void {
160	    try {
161	      channel?.close()
162	    } catch {
163	      /* ignore */
164	    }
165	    try {
166	      pc.close()
167	    } catch {
168	      /* ignore */
169	    }
170	    setState('closed')
171	  }
172	
173	  return {
174	    get state() {
175	      return state
176	    },
177	    createOffer,
178	    acceptOffer,
179	    acceptAnswer,
180	    send,
181	    onMessage,
182	    onStateChange,
183	    close,
184	  }
185	}
